insert into public.categories (slug, label, blurb, sort) values
('televize-audio', '{"cs":"Televize a audio","en":"TV and audio"}'::jsonb, '{"cs":"QLED a LED televize JVC, Sencor a TCL od 32 do 65 palců, rádia s DAB+ a reproduktory. Naladíme a zapojíme přímo u vás.","en":"JVC, Sencor and TCL QLED and LED televisions from 32 to 65 inches, DAB+ radios and speakers. We tune and set up at your home."}'::jsonb, 0),
('velke-spotrebice', '{"cs":"Velké spotřebiče","en":"Large appliances"}'::jsonb, '{"cs":"Pračky, sušičky, chladničky, myčky, sporáky a vestavné trouby Gorenje, Philco, Romo, Hisense, Brandt a Mora. Dovezeme, zapojíme a starý spotřebič odvezeme.","en":"Gorenje, Philco, Romo, Hisense, Brandt and Mora washers, dryers, fridges, dishwashers, cookers and built-in ovens. Delivered, installed, and your old appliance taken away."}'::jsonb, 1),
('male-spotrebice', '{"cs":"Malé spotřebiče","en":"Small appliances"}'::jsonb, '{"cs":"Kuchyňské roboty a vysavače ETA, kávovary De''Longhi a Philips, fritézy, konvice, žehličky a péče o tělo. Skladem na všech prodejnách.","en":"ETA kitchen machines and vacuums, De''Longhi and Philips coffee machines, air fryers, kettles, irons and personal care. In stock at every store."}'::jsonb, 2),
('pocitace-telefony', '{"cs":"Počítače a telefony","en":"Computers and phones"}'::jsonb, '{"cs":"Notebooky ASUS, HP a Lenovo, telefony Xiaomi a ZTE, tiskárny Canon a HP a síťové prvky. Nastavení a přenos dat na prodejně.","en":"ASUS, HP and Lenovo laptops, Xiaomi and ZTE phones, Canon and HP printers and networking. Set-up and data transfer in store."}'::jsonb, 3),
('naradi', '{"cs":"Elektrické a aku nářadí","en":"Power and cordless tools"}'::jsonb, '{"cs":"Vrtačky, brusky, kladiva, hoblíky a kompresory Einhell, Graphite, Makita, Bosch a Scheppach pro dílnu i profesionály. Železářství v Golčově Jeníkově, Chotěboři a Třemošnici.","en":"Einhell, Graphite, Makita, Bosch and Scheppach drills, grinders, hammers, planers and compressors for the workshop and the trade. Hardware stores in Golčův Jeníkov, Chotěboř and Třemošnice."}'::jsonb, 4),
('zahrada', '{"cs":"Zahradní technika","en":"Garden machinery"}'::jsonb, '{"cs":"Traktory a sekačky VARI, AL-KO a EGO, pily, plotostřihy, čerpadla, štípače a drtiče. Prodej, sestavení a autorizovaný servis VARI.","en":"VARI, AL-KO and EGO tractors and mowers, saws, hedge trimmers, pumps, log splitters and shredders. Sales, assembly and authorised VARI service."}'::jsonb, 5)
